<?php
declare(strict_types=1);
$base=dirname(__DIR__);require$base.'/vendor/autoload.php';require_once$base.'/src/Support/helpers.php';$app=new Ishep\Bootstrap\Application($base);$apply=in_array('--apply',$argv,true);$sql="SELECT a.*,u.name,u.email,mt.name membership_type_name FROM membership_applications a JOIN users u ON u.id=a.user_id JOIN membership_types mt ON mt.id=a.membership_type_id LEFT JOIN memberships m ON m.membership_application_id=a.id WHERE a.status='approved' AND m.id IS NULL ORDER BY a.id";$rows=$app->db()->query($sql)->fetchAll();echo($apply?'APPLY':'DRY RUN').': '.count($rows)." approved application(s) require reconciliation.\n";foreach($rows as $row){$fee=$app->finance()->effectiveFee((int)$row['membership_type_id']);$out=$fee&&Ishep\Support\Money::minor((string)$fee['amount'])>0?'membership and invoice':'membership awaiting fee configuration';echo$row['application_number'].' -> '.$out."\n";if($apply){$actor=(int)($row['reviewed_by']?:$row['user_id']);$app->financeService()->provisionApproved($row,$actor,'cli');}}if(!$apply)echo"No writes performed. Re-run with --apply only after reviewing the database and output.\n";
